INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369210, 15646, 'Aaj Tak', 'hi', '2250 की नौकरी गई! दरवाजा बंद, बारिश में रोते रहे CGL पास अभ्यर्थी', 'https://www.aajtak.in/education/news/story/jharkhand-jssc-cgl-cancellation-2250-jobless-candidates-protest-rain-edmm-rptc-2624552-2026-08-18', 'झारखंड में एक रात के फैसले ने 2250 परिवारों की दुनिया बदल दी. सरकार द्वारा JSSC-CGL परीक्षा रद्द किए जाने के बाद SO, ASO समेत विभिन्न पदों पर काम कर रहे अभ्यर्थी अचानक बेरोजगार हो गए. बीती रात कैबिनेट बैठक के तुरंत बाद ये लोग मंत्रालय के बाहर पहुंच गए. भारी बारिश में भीगते-भीगते मानव श्रृंखला बनाकर विरोध कर रहे हैं. आंखों में आंसू और चेहरे पर निराशा लिए कह रहे हैं, ‘कल तक नौकरी थी, आज सब छिन गया.’', '', '2026-08-18T06:03:59+00:00', '2026-08-18T06:40:07.935749'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
