INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370026, 15649, 'The Times of India', 'en', 'Reliance Jio brings back Jio Prime with ‘one-year price guarantee’: Details', 'https://timesofindia.indiatimes.com/technology/tech-news/reliance-jio-brings-back-jio-prime-this-time-with-one-year-price-guarantee-all-details/articleshow/133295954.cms', 'Reliance Jio has brought back its Prime membership program, catering to its vast community of over 500 million users. With this renewed offering, members enjoy a one-year price protection guarantee on their recharges, along with attractive cashback vouchers worth Rs 600 for select device setups and SIM activations. Additional perks include early access to the latest Jio devices, enhanced digital services, dedicated customer support, and exclusive future offers.', 'https://static.toiimg.com/photo/msid-133296028,imgsize-356200.cms', '2026-08-17T11:52:22+00:00', '2026-08-18T07:26:42.786288'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
