INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371741, 15649, 'Aaj Tak', 'hi', 'Jio Prime फिर से लॉन्च, 300 में 1 साल चलेगा सिम? जानें हर सवाल का जवाब', 'https://www.aajtak.in/technology/tech-news/story/jio-prime-relaunch-300-plan-all-question-answered-ttecm-dskc-2624761-2026-08-18', 'Jio ने एक बार फिर से प्राइम प्लान लॉन्च किया है. प्लान से रिचार्ज करने के बाद 1 साल तक के लिए लोगों को टैरिफ हाइक से छुटकारा मिलेगा. हालांकि लोग इस प्लान को लेकर कन्फ्यूज हो रहे हैं. आइए इसे समझते हैं.', '', '2026-08-18T08:51:26+00:00', '2026-08-18T09:13:26.571818'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
